DROP FUNCTION IF EXISTS internal.ensure_monthly_partitions();
CREATE OR REPLACE FUNCTION internal.ensure_monthly_partitions(p_months_ahead integer DEFAULT 12) RETURNS TABLE(created_partition text) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'internal', 'pg_temp' AS $function$ DECLARE f record; v_month_start timestamptz; v_month_end timestamptz; v_partition_name text; v_offset int; v_has_workspace boolean; v_has_agent boolean; v_has_user boolean; BEGIN FOR f IN SELECT * FROM internal.partitioned_families ORDER BY parent_table LOOP IF NOT EXISTS ( SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = f.parent_table AND c.relkind = 'p' ) THEN CONTINUE; END IF; FOR v_offset IN -3..GREATEST(p_months_ahead, 6) LOOP v_month_start := date_trunc('month', now() + make_interval(months => v_offset)); v_month_end := v_month_start + interval '1 month'; v_partition_name := format('%s_%s', f.partition_prefix, to_char(v_month_start, 'YYYY_MM')); IF NOT EXISTS ( SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=v_partition_name ) THEN EXECUTE format( 'CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.%I FOR VALUES FROM (%L) TO (%L)', v_partition_name, f.parent_table, v_month_start, v_month_end ); EXECUTE format( 'ALTER TABLE public.%I SET ( autovacuum_vacuum_scale_factor = 0.05, autovacuum_analyze_scale_factor = 0.01, autovacuum_vacuum_insert_scale_factor = 0.05, fillfactor = 100)', v_partition_name ); created_partition := v_partition_name; RETURN NEXT; END IF; EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', v_partition_name); EXECUTE format('GRANT ALL ON public.%I TO service_role', v_partition_name); SELECT bool_or(column_name='workspace_id'), bool_or(column_name='agent_id'), bool_or(column_name='user_id') INTO v_has_workspace, v_has_agent, v_has_user FROM information_schema.columns WHERE table_schema='public' AND table_name=v_partition_name; IF f.policy_kind='agent_traces' AND v_has_user AND v_has_agent THEN EXECUTE format('GRANT SELECT, INSERT ON public.%I TO authenticated', v_partition_name); EXECUTE format('DROP POLICY IF EXISTS "Users can see their own traces" ON public.%I', v_partition_name); EXECUTE format($p$ CREATE POLICY "Users can see their own traces" ON public.%I FOR SELECT USING (user_id = (SELECT auth.uid())) $p$, v_partition_name); EXECUTE format('DROP POLICY IF EXISTS "Admins only" ON public.%I', v_partition_name); EXECUTE format($p$ CREATE POLICY "Admins only" ON public.%I FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = %I.agent_id AND public.is_workspace_admin((SELECT auth.uid()), a.workspace_id))) WITH CHECK (EXISTS (SELECT 1 FROM public.agents a WHERE a.id = %I.agent_id AND public.is_workspace_admin((SELECT auth.uid()), a.workspace_id))) $p$, v_partition_name, v_partition_name, v_partition_name); ELSIF f.policy_kind='workspace_admin' AND v_has_workspace THEN EXECUTE format('GRANT SELECT, INSERT ON public.%I TO authenticated', v_partition_name); EXECUTE format('DROP POLICY IF EXISTS "Admins only" ON public.%I', v_partition_name); EXECUTE format($p$ CREATE POLICY "Admins only" ON public.%I FOR ALL TO authenticated USING (public.is_workspace_admin((SELECT auth.uid()), workspace_id)) WITH CHECK (public.is_workspace_admin((SELECT auth.uid()), workspace_id)) $p$, v_partition_name); ELSIF f.policy_kind='service_only' THEN EXECUTE format('REVOKE ALL ON public.%I FROM authenticated, anon', v_partition_name); EXECUTE format('DROP POLICY IF EXISTS "service only" ON public.%I', v_partition_name); EXECUTE format($p$ CREATE POLICY "service only" ON public.%I FOR ALL TO service_role USING (true) WITH CHECK (true) $p$, v_partition_name); END IF; END LOOP; END LOOP; END; $function$;
DROP FUNCTION IF EXISTS internal.capture_perf_snapshot();
CREATE OR REPLACE FUNCTION internal.capture_perf_snapshot() RETURNS TABLE(kind TEXT, rows_captured BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path = internal, public, extensions, pg_catalog AS $$ DECLARE v_idx BIGINT; v_q BIGINT; v_t BIGINT; BEGIN INSERT INTO internal.index_usage_snapshots (schemaname, relname, indexrelname, idx_scan, idx_tup_read, idx_tup_fetch, index_size_bytes, table_size_bytes, is_unique, is_primary, is_partial) SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, s.idx_tup_read, s.idx_tup_fetch, pg_relation_size(s.indexrelid), pg_relation_size(s.relid), i.indisunique, i.indisprimary, (i.indpred IS NOT NULL) FROM pg_stat_user_indexes s JOIN pg_index i ON i.indexrelid = s.indexrelid WHERE s.schemaname = 'public'; GET DIAGNOSTICS v_idx = ROW_COUNT; INSERT INTO internal.query_stats_snapshots (queryid, query_sample, calls, total_exec_ms, mean_exec_ms, max_exec_ms, rows_returned, shared_blks_hit, shared_blks_read) SELECT queryid, substring(query, 1, 500), calls, total_exec_time, mean_exec_time, max_exec_time, rows, shared_blks_hit, shared_blks_read FROM pg_stat_statements WHERE queryid IS NOT NULL ORDER BY total_exec_time DESC LIMIT 100; GET DIAGNOSTICS v_q = ROW_COUNT; INSERT INTO internal.table_activity_snapshots (schemaname, relname, n_tup_ins, n_tup_upd, n_tup_del, n_tup_hot_upd, n_live_tup, n_dead_tup, table_size_bytes, indexes_size_bytes, last_autovacuum, last_autoanalyze) SELECT s.schemaname, s.relname, s.n_tup_ins, s.n_tup_upd, s.n_tup_del, s.n_tup_hot_upd, s.n_live_tup, s.n_dead_tup, pg_relation_size(s.relid), pg_indexes_size(s.relid), s.last_autovacuum, s.last_autoanalyze FROM pg_stat_user_tables s WHERE s.schemaname = 'public'; GET DIAGNOSTICS v_t = ROW_COUNT; RETURN QUERY VALUES ('indexes', v_idx), ('queries', v_q), ('tables', v_t); END $$;
REVOKE ALL ON FUNCTION internal.ensure_monthly_partitions(integer) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION internal.ensure_monthly_partitions(integer) TO service_role;
REVOKE ALL ON FUNCTION internal.capture_perf_snapshot() FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION internal.capture_perf_snapshot() TO service_role;
